/**
 * The fables of Ésope (translated by Émile Chambry, 1927), Phèdre (translated by
 * Ernest Panckoucke, 1864) and La Fontaine (edition of 1874), from Wikisource.
 * All of them are in the public domain. Phèdre is only used when Ésope has no
 * version of the story.
 * In `text`, verses are separated by "\n" and paragraphs by "\n\n".
 * The summaries have been written for this activity, in modern French.
 *
 * After any change, run `npm run embeddings:fables` (see `../generate.mts`).
 */
import type { Author } from "../types";

export interface FableSource {
  /** The versions of Ésope and La Fontaine of the same story have the same index. */
  story: number;
  author: Author;
  title: string;
  /** Link to the full text on Wikisource. */
  url: string;
  /**
   * Short summaries of the fable, in modern French, with its moral.
   * Written with different words, to match more ways of describing the fable.
   */
  summaries: string[];
  text: string;
}

